package com.railway.servlet;import jakarta.servlet.http.*;import java.io.IOException;import com.railway.model.User;import com.railway.service.BookingService;
public class CancelBookingServlet extends HttpServlet{protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{try{User u=(User)r.getSession(false).getAttribute("user");boolean done=new BookingService().cancel(u.getId(),r.getParameter("pnr"));s.sendRedirect(r.getContextPath()+"/my-bookings?cancelled="+(done?"1":"0"));}catch(IllegalArgumentException e){s.sendError(404);}catch(Exception e){getServletContext().log("Cancellation failed",e);s.sendError(500);}}}
